-- CC_0314_idaho_wave_headshots.sql
-- Portraits for 120 of the 121 officeholders seated by CC_0309-CC_0313.
--
-- GENERATED by data/seed-id-legislature-2026/_build_cc0314.mjs. Do not hand-edit.
--
--   105 of 105  Idaho legislators        legislature.idaho.gov 2026 session directory
--     7 of   7  Boise                    cityofboise.org
--     8 of   9  Ada County               adacounty.id.gov
--
-- ═══ ALL THREE FIELDS, AND WHY ═══
--
--   politicians.photo_custom_url   THE FIELD THAT RENDERS. The address-search read path builds
--                                  its photo from COALESCE(photo_custom_url, photo_origin_url)
--                                  and never reads politician_images.
--   essentials.politician_images   carries photo_license, which the API returns to the frontend,
--                                  and the grid reads images[] FIRST.
--   politicians.photo_origin_url   provenance: the page the photograph came from.
--
-- ═══ 🔴 BOUND BY SEAT, NEVER BY NAME ═══
--
-- Production holds a SECOND Mark Harris — the U.S. Representative for North Carolina's 8th
-- district (external_id -37008) — beside Idaho's Senate District 35 member of the same name.
-- A name-bound UPDATE would paint the Idaho senator's face onto the congressman. Every
-- legislative row below resolves through (chamber, district geo_id + mtfcc, office title) ->
-- office -> office_current_holder, and the gate asserts the resolved name matches the one this
-- file was generated against.
--
-- ⚠ G5210 and G5220 SHARE a geo_id in Idaho (both 16019 for district 19), so the resolution
--   pairs geo_id with mtfcc as well as with the chamber.
--
-- ═══ 🔴 THE ADA COUNTY SHERIFF IS DELIBERATELY ABSENT ═══
--
-- adacounty.id.gov/sheriff/ publishes a departmental LOGO and a banner and no portrait of
-- Sheriff Matt Clifford. Nothing in this repo asks whether a headshot contains a face — a seal,
-- a logo, a map or a blank passes every automated check — so a scraper taking "the first image
-- on the sheriff's page" would publish a badge as a man's face. A blank beats a wrong picture.
-- ▶ 8 of Ada County's 9 seats carry a portrait; the gate asserts exactly that, so filling the
--   ninth later is a deliberate act rather than drift.
--
-- ═══ 🔴 ALL 120 WERE LOOKED AT ═══
--
-- Rendered to three contact sheets and inspected before this file was written. All 120 are
-- genuine, distinct, individual headshots. Specifically checked:
--   * Two filenames are POSITIONAL or opaque and name no person — Boise's 'mayor-2024-web.png'
--     and Ada's coroner file 'B-0043-5x300-1.jpg'. That is exactly where an off-by-one hides.
--     Both were read against the name under the frame and both are the right person; each came
--     from that officeholder's own page.
--   * Three legislature portraits are not the studio set — Anne Henderson Haws (House 16 B),
--     Erin M. Bingham (House 32 B) and Michael Leman Veile (House 35 A). All three are recent
--     ARRIVALS who have not sat for the session photograph: Bingham was appointed in January
--     2026 and Veile in September 2025. Expected, not an error.
--   * All 105 legislature files are distinct by MD5 — no placeholder is repeated across seats.
--
-- ═══ LICENCE ═══
--
-- press_use throughout. These are the Legislature's, the city's and the county's own official
-- photographs of their own officeholders. Not federal works, no free licence.
--
-- ⚠ Mirrored into Supabase storage, not hotlinked. legislature.idaho.gov serves all 105 from a
--   /sessioninfo/2026/ path that is re-cut every session, so every source URL is expected to
--   move when the 2027 directory is published. Stored as uploaded; nothing was upscaled.

-- ── Pre-flight ────────────────────────────────────────────────────────────────
DO $$
DECLARE v_seated int; v_already int;
BEGIN
  SELECT count(och.politician_id) INTO v_seated
    FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
    JOIN essentials.governments g ON g.id = c.government_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE (g.name = 'State of Idaho' AND c.name IN ('Idaho Senate','Idaho House of Representatives'))
      OR g.name IN ('City of Boise, Idaho, US', 'Ada County, Idaho, US');
  IF v_seated <> 121 THEN
    RAISE EXCEPTION 'CC_0314 pre-flight: expected 121 seated Idaho-wave offices from CC_0309-CC_0313, found %', v_seated;
  END IF;

  SELECT count(*) INTO v_already FROM essentials.politician_images pi
    JOIN essentials.politicians p ON p.id = pi.politician_id
   WHERE p.source LIKE '%(CC_031%)%' AND pi.type = 'default';
  IF v_already <> 0 THEN
    RAISE EXCEPTION 'CC_0314 pre-flight: % Idaho-wave politician(s) already carry a default image', v_already;
  END IF;
END $$;

-- ── Legislature portraits, bound by seat ──────────────────────────────────────
CREATE TEMP TABLE id_photos(
  chamber   text,
  geo_id    text,
  mtfcc     text,
  title     text,
  expect    text NOT NULL,
  file      text NOT NULL,
  origin    text NOT NULL,
  politician_id uuid
) ON COMMIT DROP;

