UPDATE id_photos h SET politician_id = och.politician_id
  FROM essentials.offices o
  JOIN essentials.chambers c ON c.id = o.chamber_id
  JOIN essentials.governments g ON g.id = c.government_id
  JOIN essentials.districts d ON d.id = o.district_id
  JOIN essentials.office_current_holder och ON och.office_id = o.id
 WHERE g.name = 'State of Idaho'
   AND c.name = h.chamber AND o.title = h.title
   AND d.geo_id = h.geo_id AND d.mtfcc = h.mtfcc AND lower(d.state) = 'id';

-- ── Boise and Ada County portraits, bound by (government, office title) ───────
CREATE TEMP TABLE id_local_photos(
  gov    text NOT NULL,
  title  text NOT NULL,
  expect text NOT NULL,
  file   text NOT NULL,
  origin text NOT NULL,
  politician_id uuid
) ON COMMIT DROP;

