UPDATE id_local_photos h SET politician_id = och.politician_id
  FROM essentials.offices o
  JOIN essentials.chambers c ON c.id = o.chamber_id
  JOIN essentials.governments g ON g.id = c.government_id
  JOIN essentials.office_current_holder och ON och.office_id = o.id
 WHERE g.name = h.gov AND o.title = h.title;

-- 🔴 Every row must have resolved, and the resolved NAME must be the one this file was
--    generated against. That second test is what makes the seat-binding meaningful.
DO $$
DECLARE v_null int; v_wrong int; r record;
BEGIN
  SELECT count(*) INTO v_null FROM (
    SELECT politician_id FROM id_photos UNION ALL SELECT politician_id FROM id_local_photos) x
   WHERE x.politician_id IS NULL;
  IF v_null <> 0 THEN RAISE EXCEPTION 'CC_0314: % portrait row(s) did not resolve to a seated person', v_null; END IF;

  v_wrong := 0;
  FOR r IN
    SELECT h.expect, p.full_name, h.file FROM id_photos h JOIN essentials.politicians p ON p.id = h.politician_id
     WHERE p.full_name <> h.expect
    UNION ALL
    SELECT h.expect, p.full_name, h.file FROM id_local_photos h JOIN essentials.politicians p ON p.id = h.politician_id
     WHERE p.full_name <> h.expect
  LOOP
    RAISE WARNING 'CC_0314: % resolves to % — the seat has turned over since this file was generated', r.file, r.full_name;
    v_wrong := v_wrong + 1;
  END LOOP;
  IF v_wrong <> 0 THEN
    RAISE EXCEPTION 'CC_0314: % portrait(s) resolve to a different person than this file was '
                    'generated against. Re-read the roster before writing faces.', v_wrong;
  END IF;
END $$;

-- 1. THE FIELD THAT RENDERS.
UPDATE essentials.politicians p SET photo_custom_url = 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || h.file
  FROM id_photos h WHERE p.id = h.politician_id;
UPDATE essentials.politicians p SET photo_custom_url = 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || h.file
  FROM id_local_photos h WHERE p.id = h.politician_id;

-- 2. The images row the grid reads FIRST, carrying the licence the API returns.
INSERT INTO essentials.politician_images (politician_id, url, type, photo_license)
SELECT h.politician_id, 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || h.file, 'default', 'press_use' FROM id_photos h
 WHERE NOT EXISTS (SELECT 1 FROM essentials.politician_images pi
                    WHERE pi.politician_id = h.politician_id AND pi.type = 'default');
INSERT INTO essentials.politician_images (politician_id, url, type, photo_license)
SELECT h.politician_id, 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || h.file, 'default', 'press_use' FROM id_local_photos h
 WHERE NOT EXISTS (SELECT 1 FROM essentials.politician_images pi
                    WHERE pi.politician_id = h.politician_id AND pi.type = 'default');

-- 3. Provenance. Written last, never into the render position.
UPDATE essentials.politicians p SET photo_origin_url = h.origin FROM id_photos h WHERE p.id = h.politician_id;
UPDATE essentials.politicians p SET photo_origin_url = h.origin FROM id_local_photos h WHERE p.id = h.politician_id;

-- ── Post-verify gate ──────────────────────────────────────────────────────────
DO $$
DECLARE v_custom int; v_img int; v_disagree int; v_lic int; v_sheriff int; v_nc int;
BEGIN
  SELECT count(*) INTO v_custom FROM essentials.politicians p
   WHERE p.photo_custom_url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'id-legislature-2026/%'
      OR p.photo_custom_url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'boise-id-2026/%'
      OR p.photo_custom_url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'ada-county-id-2026/%';
  IF v_custom <> 120 THEN RAISE EXCEPTION 'CC_0314 gate: expected 120 photo_custom_url on the CDN, found %', v_custom; END IF;

  SELECT count(*) INTO v_img FROM essentials.politician_images pi
    JOIN essentials.politicians p ON p.id = pi.politician_id
   WHERE pi.type = 'default' AND pi.url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || '%'
     AND (p.source LIKE '%(CC_0310)%' OR p.source LIKE '%(CC_0312)%' OR p.source LIKE '%(CC_0313)%');
  IF v_img <> 120 THEN RAISE EXCEPTION 'CC_0314 gate: expected 120 default politician_images rows, found %', v_img; END IF;

  -- 🔴 BOTH fields must agree. The grid reads images[] first and the backend reads the scalar;
  --    if they disagree a voter sees one face and the API reports another.
  -- ⚠ SCOPED TO THIS WAVE'S THREE PREFIXES, and that scoping is load-bearing. A first version
  --   matched the whole politician_photos bucket and failed on 26 rows — every one a
  --   PRE-EXISTING row from an earlier wave with a UUID filename, none of them Idaho's. The
  --   predicate was the defect, not the data. Those 26 are a real pre-existing disagreement in
  --   production and are left alone here deliberately: they are not this migration's to fix.
  SELECT count(*) INTO v_disagree FROM essentials.politician_images pi
    JOIN essentials.politicians p ON p.id = pi.politician_id
   WHERE pi.type = 'default'
     AND (pi.url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'id-legislature-2026/%'
       OR pi.url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'boise-id-2026/%'
       OR pi.url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'ada-county-id-2026/%')
     AND coalesce(p.photo_custom_url,'') <> pi.url;
  IF v_disagree <> 0 THEN
    RAISE EXCEPTION 'CC_0314 gate: % row(s) have photo_custom_url disagreeing with their default '
                    'politician_images url — the grid and the API would show different faces', v_disagree;
  END IF;

  SELECT count(*) INTO v_lic FROM essentials.politician_images pi
   WHERE pi.url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'id-legislature-2026/%' AND coalesce(pi.photo_license,'') <> 'press_use';
  IF v_lic <> 0 THEN RAISE EXCEPTION 'CC_0314 gate: % Idaho legislature image(s) carry the wrong licence', v_lic; END IF;

  -- 🔴 The Sheriff must STILL have no portrait. If this ever becomes 1 it was a deliberate act,
  --    not drift — his office publishes only a logo.
  SELECT count(p.photo_custom_url) INTO v_sheriff FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
    JOIN essentials.governments g ON g.id = c.government_id
    JOIN essentials.office_current_holder och ON och.office_id = o.id
    JOIN essentials.politicians p ON p.id = och.politician_id
   WHERE g.name = 'Ada County, Idaho, US' AND o.title = 'Sheriff';
  IF v_sheriff <> 0 THEN
    RAISE EXCEPTION 'CC_0314 gate: the Ada County Sheriff now carries a photo_custom_url. His office '
                    'publishes a departmental logo and no portrait — check it is a face, not a badge.';
  END IF;

  -- 🔴 The North Carolina Mark Harris must NOT have been given an Idaho face.
  SELECT count(*) INTO v_nc FROM essentials.politicians
   WHERE external_id = -37008 AND coalesce(photo_custom_url,'') LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/' || 'id-%';
  IF v_nc <> 0 THEN
    RAISE EXCEPTION 'CC_0314 gate: the North Carolina congressman Mark Harris (-37008) was given an '
                    'Idaho portrait — the seat binding failed and a name match was used instead.';
  END IF;

  RAISE NOTICE 'CC_0314 OK: 120 portraits written (105 legislature, 7 Boise, 8 Ada County), both fields agree, Sheriff deliberately blank, NC Mark Harris untouched.';
END $$;
